//! contract: reads registry handler::host_tool_descriptors
//! PRD-mcphost-output-schema-reach-sweep-live
//! AC4 (P0) -- Given `host.import` called with `dry_run: true`, When its result
//! is validated against the advertised `outputSchema`, Then it validates
//! through an `own_dry_run` branch generated by one fn beside
//! `import.rs:258-267`, and a planted second name outside `WRITE_VERBS`
//! declaring `dry_run` with no generated branch fails the sweep naming that tool.

use crate::common::TestServer;
use crate::osreach::{self, Served};
use crate::timp;
use serde_json::{Value, json};

#[tokio::test]
async fn osreach_ac04_import_dry_run_validates_through_the_own_dry_run_branch() {
    let server = TestServer::start().await;
    let source = timp::new_tenant(&server, "Osreach AC4 Source").await;
    source.seed_full().await;
    let (run_id, _) = source.export(&server).await;
    let dest = timp::new_tenant(&server, "Osreach AC4 Dest").await;

    let listed = dest.client.tools_list().await.expect("tools/list");
    let import = listed["tools"]
        .as_array()
        .expect("tools")
        .iter()
        .find(|t| t["name"].as_str().is_some_and(|n| mcphost::import::IMPORT_TOOL_NAME == osreach::canonical_of(n)))
        .expect("host.import is served")
        .clone();
    let name = import["name"].as_str().expect("name").to_string();
    let schema = import["outputSchema"].clone();

    let preview = dest.call(&name, json!({"run_id": run_id, "dry_run": true})).await;
    assert_eq!(preview["dry_run"], json!(true), "{preview}");
    osreach::check(&name, osreach::STATE_DRY_RUN, &schema, &preview).expect("served schema admits the preview");
    assert_eq!(osreach::variant_of(osreach::STATE_DRY_RUN, &preview), Some(osreach::VARIANT_OWN_DRY_RUN));

    // The admission is the generated branch's: the live view alone (without the
    // branch) is what a bare required list would have rejected.
    let branch = mcphost::import::dry_run_output_branch();
    jsonschema::validator_for(&branch).expect("branch compiles").validate(&preview).expect("branch admits the preview");
    let any_of = schema["anyOf"].as_array().expect("composed with anyOf");
    assert!(any_of.contains(&branch), "the advertised schema carries the generated branch verbatim");
}

#[test]
fn osreach_ac04_has_own_dry_run_is_the_generated_registry() {
    assert!(mcphost::output_schemas::has_own_dry_run(mcphost::import::IMPORT_TOOL_NAME));
    assert!(!mcphost::output_schemas::has_own_dry_run("planted.tool"));
}

#[test]
fn osreach_ac04_a_planted_dry_run_name_without_a_branch_fails_naming_the_tool() {
    let planted = |name: &str, dry: bool| Served {
        name: name.to_string(),
        input: if dry { json!({"properties": {"dry_run": {"type": "boolean"}}}) } else { json!({"properties": {}}) },
        output: None::<Value>,
    };
    let served = vec![
        planted(mcphost::import::IMPORT_TOOL_NAME, true),
        planted("planted.second_dry_run", true),
        planted("planted.no_dry_run", false),
    ];
    assert_eq!(osreach::undeclared_dry_run(&served), vec!["planted.second_dry_run".to_string()]);
    let mut rows = std::collections::BTreeMap::new();
    for s in &served {
        let mut row = osreach::ToolRow::default();
        let schema = json!({"type": "object", "required": ["n"]});
        row.failures.extend(osreach::check(&s.name, osreach::STATE_DRY_RUN, &schema, &json!({"other": 1})).err());
        rows.insert(s.name.clone(), row);
    }
    let err = osreach::require_dry_run_branches(&served, &rows).expect_err("the planted name fails the sweep");
    assert!(err.contains("planted.second_dry_run"), "{err}");
    assert!(!err.contains(mcphost::import::IMPORT_TOOL_NAME), "{err}");
}

#[tokio::test]
async fn osreach_ac04_the_served_set_has_no_undeclared_dry_run_name() {
    let sweep = osreach::sweep().await;
    if let Err(e) = osreach::require_dry_run_branches(&sweep.served, &sweep.rows) {
        panic!("{e}");
    }
}
